// Jev (TypeSafe System One) review of the rebase/refactor closeout.
// Usage: node jev-check.mjs <repoRoot>
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';

const repo = process.argv[2];
const env = readFileSync(join(repo, '.env'), 'utf8');
const key = env.match(/^TYPESAFE_API_KEY=(.*)$/m)?.[1]?.trim().replace(/^['"]|['"]$/g, '');
if (!key) throw new Error('TYPESAFE_API_KEY missing from .env');

const git = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
const cap = (s, n) => (s.length > n ? s.slice(0, n) + `\n…[truncated ${s.length - n} chars]` : s);

let inTok = 0, outTok = 0, calls = 0;
async function judge(state, questions) {
    const res = await fetch('https://api.typesafe.ai/v1/systemone', {
        method: 'POST',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'jev-latest', state, questions }),
        signal: AbortSignal.timeout(120_000),
    });
    const body = await res.text();
    if (!res.ok) throw new Error(`TypeSafe HTTP ${res.status}: ${body.slice(0, 300)}`);
    const json = JSON.parse(body);
    calls++; inTok += json.usage?.input_tokens ?? 0; outTok += json.usage?.output_tokens ?? 0;
    return json;
}
