// Renderer import-reachability scan. Usage: node reach.mjs <repoRoot>
// Finds renderer source files (non-test) unreachable from production entry points,
// and separately those reachable only through test files.
import { readFileSync, existsSync, statSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, dirname, resolve, relative } from 'node:path';

const repo = process.argv[2];
const R = join(repo, 'packages/renderer');
const files = execFileSync('git', ['ls-files', 'packages/renderer/src', 'packages/shared/src', 'agents'], { cwd: repo, encoding: 'utf8' })
    .split('\n').filter(f => /\.(ts|tsx|js|mjs)$/.test(f)).map(f => join(repo, f));
const isTest = f => /\.(test|spec)\.|__tests__|\/test\/|__mocks__|\.stories\./.test(f);
const exts = ['', '.ts', '.tsx', '.js', '.mjs', '/index.ts', '/index.tsx', '/index.js'];
const aliases = [
    ['@/', join(R, 'src/')], ['@agents/', join(repo, 'agents/')], ['@shared/', join(repo, 'packages/shared/src/')],
    ['@indii/shared/', join(repo, 'packages/shared/src/')],
];
function tryResolve(base) {
    for (const e of exts) { const p = base + e; if (existsSync(p) && statSync(p).isFile()) return p; }
    return null;
}
function resolveSpec(spec, from) {
    if (spec === '@indii/shared') return join(repo, 'packages/shared/src/index.ts');
    for (const [a, t] of aliases) if (spec.startsWith(a)) return tryResolve(t + spec.slice(a.length));
    if (spec.startsWith('.')) return tryResolve(resolve(dirname(from), spec));
    return null; // package import
}
const re = /(?:import|export)\s+(?:type\s+)?(?:[^'"`;]*?\sfrom\s*)?['"]([^'"]+)['"]|import\(\s*['"]([^'"]+)['"]\s*\)|require\(\s*['"]([^'"]+)['"]\s*\)|vi\.(?:mock|importActual)\(\s*['"]([^'"]+)['"]|new URL\(\s*['"]([^'"]+)['"]\s*,\s*import\.meta\.url/g;
const edges = new Map();
for (const f of files) {
    let src; try { src = readFileSync(f, 'utf8'); } catch { continue; }
    const out = new Set();
    for (const m of src.matchAll(re)) {
        const spec = m[1] || m[2] || m[3] || m[5]; // ignore vi.mock targets (m[4]) as reachers
        if (!spec) continue;
        const r = resolveSpec(spec.replace(/\?.*$/, ''), f);
        if (r) out.add(r);
    }
    // import.meta.glob patterns: mark directory as reached
    for (const m of src.matchAll(/import\.meta\.glob\(\s*\[?\s*['"]([^'"]+)['"]/g)) out.add('GLOB:' + resolve(dirname(f), m[1].startsWith('@/') ? join(R, 'src', m[1].slice(2)) : m[1]));
    edges.set(f, out);
}
function walk(roots) {
    const seen = new Set(); const stack = [...roots];
    const globs = [];
    while (stack.length) {
        const f = stack.pop(); if (seen.has(f)) continue; seen.add(f);
        for (const n of edges.get(f) ?? []) {
            if (n.startsWith('GLOB:')) { globs.push(n.slice(5)); continue; }
            if (!seen.has(n)) stack.push(n);
        }
    }
    return { seen, globs };
}
const entries = ['src/main.tsx', 'src/startupWatchdog.ts'].map(p => join(R, p));
// Extra production roots: workers, electron preload references, vite config inputs
for (const f of files) if (/\.worker\.(ts|js)$|\/workers\//.test(f) && !isTest(f)) entries.push(f);
const prod = walk(entries);
const withTests = walk([...entries, ...files.filter(isTest)]);
const globMatch = f => prod.globs.some(g => { const prefix = g.split('*')[0]; return f.startsWith(prefix); });
const src = files.filter(f => f.startsWith(join(R, 'src')) && !isTest(f));
const lines = f => readFileSync(f, 'utf8').split('\n').length;
const dead = src.filter(f => !prod.seen.has(f) && !globMatch(f));
const testOnly = dead.filter(f => withTests.seen.has(f));
const fullyDead = dead.filter(f => !withTests.seen.has(f));
const sum = a => a.reduce((s, f) => s + lines(f), 0);
// tests whose subject is unreachable in prod
const tests = files.filter(f => f.startsWith(join(R, 'src')) && isTest(f));
const deadSet = new Set(dead);
const orphanTests = tests.filter(t => [...(edges.get(t) ?? [])].some(n => deadSet.has(n)) && ![...(edges.get(t) ?? [])].some(n => prod.seen.has(n) && !n.includes('/test/')));
const rel = f => relative(repo, f);
const byDir = {};
for (const f of dead) { const d = rel(f).split('/').slice(0, 5).join('/'); byDir[d] = (byDir[d] ?? 0) + lines(f); }
console.log(JSON.stringify({
    rendererSourceFiles: src.length, rendererSourceLines: sum(src),
    prodReachableFiles: src.filter(f => prod.seen.has(f)).length,
    unreachable: { files: dead.length, lines: sum(dead) },
    reachableOnlyFromTests: { files: testOnly.length, lines: sum(testOnly) },
    reachableFromNothing: { files: fullyDead.length, lines: sum(fullyDead) },
    testsOnlyExercisingDeadCode: { files: orphanTests.length, lines: sum(orphanTests) },
    topDeadDirs: Object.entries(byDir).sort((a, b) => b[1] - a[1]).slice(0, 25),
    biggestDeadFiles: dead.map(f => [rel(f), lines(f), withTests.seen.has(f) ? 'test-only' : 'none']).sort((a, b) => b[1] - a[1]).slice(0, 40),
}, null, 1));

