// Jev classification of prune candidates. Usage: node jev-prune.mjs <mainRepo> <worktree> <batch.tsv> <out.json>
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { basename } from 'node:path';

const [repo, wt, list, outPath] = process.argv.slice(2);
const key = readFileSync(repo + '/.env', 'utf8').match(/^TYPESAFE_API_KEY=REDACTED, '');
const git = (...a) => execFileSync('git', a, { cwd: wt, encoding: 'utf8' }).trim();
const rows = readFileSync(list, 'utf8').trim().split('\n').map(l => l.split('\t')).map(([n, f]) => ({ lines: +n, file: f }));

const CRITERIA = {
    obsolete: 'Obsolete or superseded: an older version, abandoned experiment, or replaced by another implementation',
    unused_utility: 'Small generic helper/type/constant nobody uses; no product value lost by deleting',
    unwired_feature: 'A substantial, apparently finished user-facing feature or service that was never wired in and may be worth connecting instead of deleting',
    unclear: 'Not enough evidence to tell',
};
let calls = 0, inTok = 0, outTok = 0;
const results = [];
for (let i = 0; i < rows.length; i += 20) {
    const chunk = rows.slice(i, i + 20);
    const files = {};
    const questions = {};
    chunk.forEach((r, k) => {
        const src = readFileSync(`${wt}/${r.file}`, 'utf8');
        const last = git('log', '-1', '--format=%ad %s', '--date=short', '--', r.file);
        const stem = basename(r.file).replace(/\.(tsx?|jsx?)$/, '');
        let similar = '';
        try { similar = git('ls-files', `*${stem}*`).split('\n').filter(p => p !== r.file && !/\.(test|spec)\./.test(p)).slice(0, 4).join(', '); } catch { /* none */ }
        files[`f${k}`] = { path: r.file, lines: r.lines, lastCommit: last, otherFilesWithSimilarName: similar || 'none', head: src.slice(0, 1800) };
        questions[`f${k}`] = { type: 'choice', instructions: `File f${k} (${r.file}) is imported by nothing in the app or its tests. Classify it.`, criteria: CRITERIA };
    });
    const res = await fetch('https://api.typesafe.ai/v1/systemone', {
        method: 'POST', headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'jev-latest', state: { context: 'indii: AI music-business platform for independent artists (React/Electron). Deciding whether unreferenced renderer source files can be deleted.', files }, questions }),
        signal: AbortSignal.timeout(180_000),
    });
    const body = await res.text();
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${body.slice(0, 300)}`);
    const j = JSON.parse(body); calls++; inTok += j.usage?.input_tokens ?? 0; outTok += j.usage?.output_tokens ?? 0;
    chunk.forEach((r, k) => results.push({ ...r, ...(j.answers?.[`f${k}`] ?? {}) }));
}
writeFileSync(outPath, JSON.stringify({ calls, inputTokens: inTok, outputTokens: outTok, results }, null, 1));
const tally = {};
for (const r of results) { const c = (r.confidence ?? 0) < 0.65 ? `${r.choice}(low)` : r.choice; tally[c] = tally[c] ?? [0, 0]; tally[c][0]++; tally[c][1] += r.lines; }
console.log(JSON.stringify({ calls, inTok, outTok, tally }));

