function NeuralSyncPulse({ lastPulse }: { lastPulse: string | null }) {
    // We drive the animation purely via a remounting key derived from lastPulse.
    // AnimatePresence replays the `initial → animate` motion whenever the key changes.
    const pulseKey = lastPulse ?? 'none';

    return (
        <div className="flex items-center gap-3 p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
            <div className="relative flex items-center justify-center w-8 h-8">
                <Radio size={16} className="text-emerald-400 relative z-10" />
                <AnimatePresence mode="wait">
                    {lastPulse && (
                        <motion.div
                            key={pulseKey}
                            className="absolute inset-0 rounded-full bg-emerald-500/30"
                            initial={{ scale: 0.8, opacity: 0.8 }}
                            animate={{ scale: 2.4, opacity: 0 }}
                            transition={{ duration: 1.1, ease: 'easeOut' }}
                        />
                    )}
                </AnimatePresence>
            </div>
            <div className="flex-1 min-w-0">

    const { user } = useStore(useShallow(s => ({ user: s.user })));

    const checkBudget = useCallback(async () => {
        setBreakerState('loading');
        try {
            const result = await MembershipService.checkBudget(0);
            setBudget(result);

            if (!result.allowed) {
                setBreakerState('open');
            } else if (result.requiresApproval) {
                setBreakerState('half-open');
            } else {
                setBreakerState('closed');
            }

            setLastChecked(new Date());
        } catch {
            // Unable to reach budget service — treat as unknown/closed
            setBreakerState('closed');
            setBudget(null);
        }
    }, []);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const result = await MembershipService.checkBudget(0);
                if (cancelled) return;
                setBudget(result);

                if (!result.allowed) {
                    setBreakerState('open');
                } else if (result.requiresApproval) {
                    setBreakerState('half-open');
                } else {
                    setBreakerState('closed');
                }

                setLastChecked(new Date());
            } catch {
                if (!cancelled) {
                    setBreakerState('closed');
                    setBudget(null);
                }
            }
        })();
        return () => { cancelled = true; };
    }, []);

