// Jev wire-readiness triage. Usage: node jev-wire.mjs <mainRepo> <worktree> <wire.tsv> <reach.json> <history.tsv> <out.json>
import { readFileSync, writeFileSync } from 'node:fs';
import { basename, join } from 'node:path';

const [repo, wt, list, reachPath, histPath, outPath] = process.argv.slice(2);
const key = readFileSync(repo + '/.env', 'utf8').match(/^TYPESAFE_API_KEY=REDACTED, '');
const R = 'packages/renderer/src/';
const reach = JSON.parse(readFileSync(reachPath, 'utf8'));
const dead = new Set(reach.allDead.map(([f]) => f));
const hist = Object.fromEntries(readFileSync(histPath, 'utf8').trim().split('\n').map(l => l.split('\t')).map(a => [a[1], `${a[2]}; last-import-history: ${a[3]}`]));
const rows = readFileSync(list, 'utf8').trim().split('\n').map(l => l.split('\t')).map(([n, f]) => ({ lines: +n, file: f }));
const allFiles = reach.rendererSourceFilesList ?? null;

function resolveImport(spec, from) {
    if (spec.startsWith('@/')) return R + spec.slice(2);
    if (spec.startsWith('.')) return join(from.split('/').slice(0, -1).join('/'), spec);
    return null;
}
const CRITERIA = {
    wire_ready: 'Complete and real: its data source/backend is live (its imports are prod-reachable services) and it has an obvious host screen or caller, so connecting it needs only an import + mount/call',
    needs_backend: 'Would need new backend, credentials, or a consumer that does not exist yet (e.g. data it writes is never read, external API with no key or proxy), so wiring now creates a dead or misleading control',
    superseded: 'A live file already provides the same feature (an older twin/fork), so wiring would duplicate it',
    demo_or_stub: 'Decorative, simulated, mock, or placeholder content with no real behaviour',
    unclear: 'Not enough evidence',
};
let calls = 0, inTok = 0, outTok = 0;
const results = [];
for (let i = 0; i < rows.length; i += 12) {
    const chunk = rows.slice(i, i + 12);
    const files = {}, questions = {};
    chunk.forEach((r, k) => {
        const path = R + r.file;
        const src = readFileSync(join(wt, path), 'utf8');
        const imports = [...src.matchAll(/from\s+['"]([^'"]+)['"]/g)].map(m => m[1]).filter(s => s.startsWith('@/') || s.startsWith('.'));
        const importStatus = imports.map(s => {
            const p = resolveImport(s, path);
            const isDead = p && [...dead].some(d => d === p || d.startsWith(p + '.') || d === p + '/index.ts');
            return `${s} => ${isDead ? 'ALSO-UNWIRED' : 'live'}`;
        });
        const stem = basename(r.file).replace(/\.(tsx?|ts)$/, '').toLowerCase().replace(/(service|panel|list|hook|use)/g, '');
        const twins = (reach.liveFiles ?? []).filter(f => stem.length > 4 && f.toLowerCase().includes(stem)).slice(0, 5);
        files[`f${k}`] = { path, lines: r.lines, history: hist[r.file] ?? '', importStatus, liveFilesWithSimilarName: twins, source: src.slice(0, 5000) };
        questions[`f${k}`] = { type: 'choice', instructions: `File f${k} (${path}) is imported by nothing. The owner wants every real, unconnected feature wired into the app. Classify how ready it is to wire.`, criteria: CRITERIA };
    });
    const res = await fetch('https://api.typesafe.ai/v1/systemone', {
        method: 'POST', headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'jev-latest', state: { context: 'indii: AI music-business platform for independent artists (React/Electron renderer). Rule: no mock data, no dead controls; a toggle must actually do what it says.', files }, questions }),
        signal: AbortSignal.timeout(240_000),
    });
    const body = await res.text();
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${body.slice(0, 300)}`);
    const j = JSON.parse(body); calls++; inTok += j.usage?.input_tokens ?? 0; outTok += j.usage?.output_tokens ?? 0;
    chunk.forEach((r, k) => results.push({ ...r, ...(j.answers?.[`f${k}`] ?? {}) }));
}
writeFileSync(outPath, JSON.stringify({ calls, inputTokens: inTok, outputTokens: outTok, results }, null, 1));
const tally = {};
for (const r of results) { const c = (r.confidence ?? 0) < 0.65 ? `${r.choice}(low)` : r.choice; tally[c] = (tally[c] ?? 0) + 1; }
console.log(JSON.stringify({ calls, inTok, outTok, tally }));

